const color = ["primary", "secondary", "success", "info", "warning", "error", "neutral"] as const;

const variant = ["solid", "outline", "soft", "subtle"] as const;

const size = [
  "xs",
  "sm",
  "default",
  "md",
  "lg",
  "xl",
  "2xl",
] as const;

export { color as buttonColors, variant as buttonVariants, size as buttonSizes };

export default {
  slots: {
    base: "reborn-button inline-flex items-center justify-center gap-2 whitespace-nowrap transition-all cursor-pointer disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
    label: "truncate",
    leadingIcon: "shrink-0",
    leadingAvatar: "shrink-0",
    leadingAvatarSize: "",
    trailingIcon: "shrink-0",
  },
  variants: {
    fieldGroup: {
      horizontal:
        "not-only:first:rounded-e-none not-only:last:rounded-s-none not-last:not-first:rounded-none focus-visible:z-[1]",
      vertical:
        "not-only:first:rounded-b-none not-only:last:rounded-t-none not-last:not-first:rounded-none focus-visible:z-[1]",
    },
    color: {
      primary: "",
      secondary: "",
      success: "",
      info: "",
      warning: "",
      error: "",
      neutral: "",
    },
    variant: {
      solid: "",
      outline: "",
      soft: "",
      subtle: "",
    },
    size: {
      xs: {
        base: "h-button-xs text-caption-lg leading-[1.5] gap-1.5 px-3 has-[>svg]:px-2.5",
      },
      sm: {
        base: "h-button-sm text-body-sm leading-[1.5] gap-1.5 px-3 has-[>svg]:px-2.5",
      },
      default: {
        base: "h-button-base text-body-base leading-[1.5] px-4 has-[>svg]:px-3",
      },
      md: { base: "h-button-base text-body-base leading-[1.5] px-4 has-[>svg]:px-3" },
      lg: { base: "h-button-lg text-title-md leading-[1.5] px-5 has-[>svg]:px-4" },
      xl: { base: "h-button-xl text-title-lg leading-[1.5] px-6 has-[>svg]:px-4" },
      "2xl": { base: "h-button-2xl text-title-xl leading-[1.5] px-6 has-[>svg]:px-4" },
    },
    gap: {
      true: {
        base: '[.reborn-button_+_&]:ml-2',
      },
      false: '',
    },
    disabled: {
      true: "cursor-not-allowed opacity-70",
      false: ""
    },
    round: {
      true: {
        base: "rounded-full",
      },
      false: "",
    },
    circle: {
      true: {
        base: "!aspect-square !w-auto !p-0 has-[>svg]:!p-0 rounded-full",
      },
      false: "",
    },
  },
  compoundVariants: [
    // Solid Variants
    {
      color: "primary" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-primary text-white hover:bg-primary/75",
    },
    {
      color: "secondary" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-secondary text-white hover:bg-secondary/75",
    },
    {
      color: "success" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-success text-white hover:bg-success/75",
    },
    {
      color: "info" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-info text-white hover:bg-info/75",
    },
    {
      color: "warning" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-warning text-white hover:bg-warning/75",
    },
    {
      color: "error" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-error text-white hover:bg-error/75",
    },
    {
      color: "neutral" as (typeof color)[number],
      variant: "solid" as (typeof variant)[number],
      class: "bg-neutral text-white hover:bg-neutral/75",
    },

    {
      color: "primary" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-primary border border-primary hover:bg-primary/10",
    },
    {
      color: "secondary" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-secondary border border-secondary hover:bg-secondary/10 disabled:bg-gray-2 disabled:border-gray-4 disabled:text-gray-6",
    },
    {
      color: "success" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-success border border-success hover:bg-success/10 disabled:bg-gray-2 disabled:border-gray-4 disabled:text-gray-6",
    },
    {
      color: "info" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-info border border-info hover:bg-info/10 disabled:bg-gray-2 disabled:border-gray-4 disabled:text-gray-6",
    },
    {
      color: "warning" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-warning border border-warning hover:bg-warning/10 disabled:bg-gray-2 disabled:border-gray-4 disabled:text-gray-6",
    },
    {
      color: "error" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-error border border-error hover:bg-error/10 disabled:bg-gray-2 disabled:border-gray-4 disabled:text-gray-6",
    },
    {
      color: "neutral" as (typeof color)[number],
      variant: "outline" as (typeof variant)[number],
      class:
        "bg-transparent text-neutral border border-neutral hover:bg-neutral/10",
    },
    {
      variant: "solid" as (typeof variant)[number],
      disabled: true,
      class: "bg-gray-6 dark:bg-gray-2 text-white/50",
    },
    {
      variant: "soft" as (typeof variant)[number],
      disabled: true,
      class: "bg-gray-6 dark:bg-gray-2 text-gray-4",
    },
    {
      variant: "subtle" as (typeof variant)[number],
      disabled: true,
      class: "bg-gray-6 dark:bg-gray-2 ring-1 ring-inset ring-[--color-gray-7] text-gray-4",
    },
    {
      variant: "outline" as (typeof variant)[number],
      disabled: true,
      class: "bg-gray-2 dark:bg-gray-8 border-gray-4 text-gray-6",
    },

    {
      color: "primary" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-primary/10 text-primary hover:bg-primary/20",
    },
    {
      color: "secondary" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-secondary/10 text-secondary hover:bg-secondary/20",
    },
    {
      color: "success" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-success/10 text-success hover:bg-success/20",
    },
    {
      color: "info" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-info/10 text-info hover:bg-info/20",
    },
    {
      color: "warning" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-warning/10 text-warning hover:bg-warning/20",
    },
    {
      color: "error" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-error/10 text-error hover:bg-error/20",
    },
    {
      color: "neutral" as (typeof color)[number],
      variant: "soft" as (typeof variant)[number],
      class: "bg-neutral/10 text-neutral hover:bg-neutral/20",
    },

    {
      color: "primary" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class: "bg-primary/10 ring-1 ring-inset ring-primary text-primary hover:bg-primary/20",
    },
    {
      color: "secondary" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class:
        "bg-secondary/10 ring-1 ring-inset ring-secondary text-secondary hover:bg-secondary/20",
    },
    {
      color: "success" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class: "bg-success/10 ring-1 ring-inset ring-success text-success hover:bg-success/20",
    },
    {
      color: "info" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class: "bg-info/10 ring-1 ring-inset ring-info text-info hover:bg-info/20",
    },
    {
      color: "warning" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class: "bg-warning/10 ring-1 ring-inset ring-warning text-warning hover:bg-warning/20",
    },
    {
      color: "error" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class: "bg-error/10 ring-1 ring-inset ring-error text-error hover:bg-error/20",
    },
    {
      color: "neutral" as (typeof color)[number],
      variant: "subtle" as (typeof variant)[number],
      class: "bg-neutral/10 ring-1 ring-inset ring-neutral text-neutral hover:bg-neutral/20",
    },
  ],
  defaultVariants: {
    color: "primary" as (typeof color)[number],
    variant: "solid" as (typeof variant)[number],
    size: "md" as (typeof size)[number],
  },
};

export const buttonColors = ['primary', 'secondary', 'success', 'info', 'warning', 'error', 'neutral'] as const
export const buttonVariants = ['solid', 'outline', 'soft', 'subtle'] as const

export const buttonSizes = [
  'xs',
  'sm',
  'default',
  'md',
  'lg',
  'xl',
  '2xl',
] as const

export default {
  slots: {
    base: 'reborn-button flex flex-row items-center justify-center relative box-border border-transparent border border-solid transition-[background-color,border-color,opacity] duration-300 overflow-visible',
    inner: 'reborn-button-clicker absolute inset-0 z-10 m-0 size-full p-0 opacity-0',
    label: 'truncate',
    loading: 'flex items-center justify-center',
    leadingIcon: 'shrink-0',
    leadingAvatar: 'shrink-0',
    leadingAvatarSize: '',
    trailingIcon: 'shrink-0',
  },
  variants: {
    color: {
      primary: '',
      secondary: '',
      success: '',
      info: '',
      warning: '',
      error: '',
      neutral: '',
    },
    block: {
      true: {
        base: 'flex'
      },
      false: {
        base: 'inline-flex',
      }
    },
    variant: {
      solid: '',
      outline: '',
      soft: '',
      subtle: '',
    },
    disabled: {
      true: '',
      false: '',
    },
    round: {
      true: {
        base: '!rounded-full',
      },
      false: '',
    },
    size: {
      'xs': {
        base: 'h-button-xs px-3 text-22 gap-1.5 rounded-[6px]',
        loading: 'size-3',
      },
      'sm': {
        base: 'h-button-sm px-3 text-24 gap-1.5 rounded-[6px]',
        loading: 'size-3.5',
      },
      'default': {
        base: 'h-button-md px-4 text-26 gap-1.5 rounded-[8px]',
        loading: 'size-4',
      },
      'md': {
        base: 'h-button-md px-4 text-26 gap-1.5 rounded-[8px]',
        loading: 'size-4',
      },
      'lg': {
        base: 'h-button-lg px-6 text-28 gap-1.5 rounded-[10px]',
        loading: 'size-5',
      },
      'xl': {
        base: 'h-button-xl px-6 text-30 gap-2 rounded-[12px]',
        loading: 'size-6',
      },
      '2xl': {
        base: 'h-button-2xl px-6 text-32 gap-2 rounded-[14px]',
        loading: 'size-7',
      },
    },
    loading: {
      true: 'pointer-events-none opacity-80',
      false: '',
    },
    gap: {
      true: {
        base: '[.reborn-button_+_&]:ml-2',
      },
      false: '',
    },
    circle: {
      true: {
        base: 'p-0 !rounded-full',
      },
      false: '',
    },
  },
  compoundVariants: [
    { circle: true, size: 'xs' as (typeof buttonSizes)[number], class: { base: 'w-button-xs' } },
    { circle: true, size: 'sm' as (typeof buttonSizes)[number], class: { base: 'w-button-sm' } },
    { circle: true, size: 'md' as (typeof buttonSizes)[number], class: { base: 'w-button-md' } },
    { circle: true, size: 'default' as (typeof buttonSizes)[number], class: { base: 'w-button-md' } },
    { circle: true, size: 'lg' as (typeof buttonSizes)[number], class: { base: 'w-button-lg' } },
    { circle: true, size: 'xl' as (typeof buttonSizes)[number], class: { base: 'w-button-xl' } },
    { circle: true, size: '2xl' as (typeof buttonSizes)[number], class: { base: 'w-button-2xl' } },
    {
      color: 'primary' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-primary border-primary text-white hover:bg-primary/90',
    },
    {
      color: 'secondary' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-secondary border-secondary text-secondary-foreground hover:bg-secondary/90',
    },
    {
      color: 'success' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-success border-success text-white hover:bg-success/90',
    },
    {
      color: 'info' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-info border-info text-white hover:bg-info/90',
    },
    {
      color: 'warning' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-warning border-warning text-white hover:bg-warning/90',
    },
    {
      color: 'error' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-error border-error text-white hover:bg-error/90',
    },
    {
      color: 'neutral' as (typeof buttonColors)[number],
      variant: 'solid' as (typeof buttonVariants)[number],
      class: 'bg-neutral border-neutral text-white hover:bg-neutral/90',
    },

    {
      color: 'primary' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-primary border-primary hover:bg-primary-50',
    },
    {
      color: 'secondary' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-secondary border-secondary hover:bg-secondary-50',
    },
    {
      color: 'success' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-success border-success hover:bg-success-50',
    },
    {
      color: 'info' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-info border-info hover:bg-info-50',
    },
    {
      color: 'warning' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-warning border-warning hover:bg-warning-50',
    },
    {
      color: 'error' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-error border-error hover:bg-error-50',
    },
    {
      color: 'neutral' as (typeof buttonColors)[number],
      variant: 'outline' as (typeof buttonVariants)[number],
      class:
        'bg-transparent text-neutral border-neutral hover:bg-neutral-50',
    },

    {
      color: 'primary' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-primary/10 border-transparent text-primary hover:bg-primary/20',
    },
    {
      color: 'secondary' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-secondary/10 border-transparent text-secondary hover:bg-secondary/20',
    },
    {
      color: 'success' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-success/10 border-transparent text-success hover:bg-success/20',
    },
    {
      color: 'info' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-info/10 border-transparent text-info hover:bg-info/20',
    },
    {
      color: 'warning' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-warning/10 border-transparent text-warning hover:bg-warning/20',
    },
    {
      color: 'error' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-error/10 border-transparent text-error hover:bg-error/20',
    },
    {
      color: 'neutral' as (typeof buttonColors)[number],
      variant: 'soft' as (typeof buttonVariants)[number],
      class: 'bg-neutral/10 border-transparent text-neutral hover:bg-neutral/20',
    },

    {
      color: 'primary' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class: 'bg-primary/10 border-primary text-primary hover:bg-primary/20',
    },
    {
      color: 'secondary' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class:
        'bg-secondary/10 border-secondary text-secondary hover:bg-secondary/20',
    },
    {
      color: 'success' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class: 'bg-success/10 border-success text-success hover:bg-success/20',
    },
    {
      color: 'info' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class: 'bg-info/10 border-info text-info hover:bg-info/20',
    },
    {
      color: 'warning' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class: 'bg-warning/10 border-warning text-warning hover:bg-warning/20',
    },
    {
      color: 'error' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class: 'bg-error/10 border-error text-error hover:bg-error/20',
    },
    {
      color: 'neutral' as (typeof buttonColors)[number],
      variant: 'subtle' as (typeof buttonVariants)[number],
      class: 'bg-neutral/10 border-neutral text-neutral hover:bg-neutral/20',
    },

    {
      variant: 'solid' as (typeof buttonVariants)[number],
      disabled: true,
      class: '!bg-gray-4 !border-gray-4 !text-white hover:!bg-gray-4 hover:!border-gray-4',
    },
    {
      variant: 'outline' as (typeof buttonVariants)[number],
      disabled: true,
      class: '!bg-gray-2 !border-gray-4 !text-gray-6 hover:!bg-gray-2 hover:!border-gray-4',
    },
    {
      variant: 'soft' as (typeof buttonVariants)[number],
      disabled: true,
      class: '!bg-gray-2 !border-transparent !text-gray-6 hover:!bg-gray-2',
    },
    {
      variant: 'subtle' as (typeof buttonVariants)[number],
      disabled: true,
      class: '!bg-gray-2 !border-gray-4 !text-gray-6 hover:!bg-gray-2 hover:!border-gray-4',
    },
  ],
  defaultVariants: {
    color: 'primary' as (typeof buttonColors)[number],
    variant: 'solid' as (typeof buttonVariants)[number],
    size: 'md' as (typeof buttonSizes)[number],
    block: false,
    loading: false
  },
}
